/** Polls until the check holds or half a second has passed, whichever comes first. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Terminates a suite's own clients, then stops each of its servers once it has seen its sockets close. */
export async function closeWhenIdle(clientsOfSuite: WebSocket[], serversOfSuite: HalServer[]): Promise<void> {
  for (const client of clientsOfSuite.splice(0)) client.terminate();
  for (const hal of serversOfSuite.splice(0)) {
    const {wss} = hal;
    await eventually(() => wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the required members, so an optional one can be added, replaced or left out per test. */
